select * from jsonb_to_recordset($CITY$[{"ord": 1, "city_id": "vancouver", "author_nickname": "\ud038\uc5d8\ub9ac\uc790\ubca0\uc2a4\uacf5\uc6d0", "tag_slug": "life", "title": "\uae38\uac00 \ud30c\ud074\ub9bf\uc740 \uc8fc\ucc28\uce78\uc744 \uc26c\ub294 \uc790\ub9ac\ub85c \ubc14\uafbc \uacf5\uac04\uc774\ub124", "body": "\uc608\uc804\uc5d4 \uae38\uac00\uc5d0 \ud280\uc5b4\ub098\uc628 \uc790\ub9ac\ub97c \uac00\uac8c \ud14c\ub77c\uc2a4\ucbe4\uc73c\ub85c \uc0dd\uac01\ud588\ub294\ub370, \ud30c\ud074\ub9bf\uc740 \uc8fc\ucc28\uce78 \uc704\uc5d0 \uacf5\uc6a9 \uc758\uc790\ub791 \uc2dd\ubb3c\uc744 \ub193\uc740 \uacf5\uac04\uc784\n\uac77\ub2e4\uac00 \uc7a0\uae50 \uc549\ub294 \uc790\ub9ac\ub3c4 \uac70\ub9ac\uc758 \ud55c \ubd80\ubd84\uc774\ub77c\ub2c8 \ub9c8\uc74c\uc774 \uc880 \ub290\uae0b\ud574\uc9d0, \uc5b4\ub514\uc11c \uc26c\uc5b4\ubcfc\uc9c0\ub294 \uc544\uc9c1 \uc0dd\uac01 \uc911", "source": "https://vancouver.ca/streets-transportation/parklets.aspx"}, {"ord": 2, "city_id": "vancouver", "author_nickname": "\uc608\uc77c\ud0c0\uc6b4\ub7f0\uce58", "tag_slug": "life", "title": "\ubc34\ucfe0\ubc84 \uae38\uac00 \uc791\ud488\ub3c4 \uc774\ub984\uacfc \uc791\uac00\uac00 \ub530\ub85c \uc788\ub124", "body": "\uae38\uac00\uc5d0\uc11c \uc791\ud488 \ubcf4\ub294 \uc0ac\ub78c\ub4e4\ucc98\ub7fc \ub098\ub3c4 \uc774\ub984\ubd80\ud130 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc5b4\uc11c \uacf5\uacf5\ubbf8\uc220 \ubaa9\ub85d \ucc98\uc74c \uc0b4\ud3b4\ubd04\n\ubc34\ucfe0\ubc84 \uacf5\uacf5\ubbf8\uc220 \ubaa9\ub85d\uc5d4 \uc791\ud488 \uc774\ub984\u00b7\uc791\uac00\u00b7\uc704\uce58\uac00 \uac19\uc774 \uc788\uace0, \uc2dc\uac00 \uc758\ub8b0\ud55c \uc791\ud488 \ub9d0\uace0 \ubb38\ud654\u00b7\uc5ed\uc0ac\uc801\uc73c\ub85c \uc911\uc694\ud55c \uac83\ub4e4\ub3c4 \ub4e4\uc5b4 \uc788\uc5b4\n\uc774\uc81c\ub294 \uadf8\ub0e5 \uc870\ud615\ubb3c\uc774\ub77c\uace0 \ubb49\ub6b1\uadf8\ub9ac\uc9c0 \uc54a\uace0 \uc775\uc219\ud55c \uae38\uc758 \uc791\ud488 \ud558\ub098\ubd80\ud130 \uae30\uc5b5\ud560 \uac70\uc57c", "source": "https://covapp.vancouver.ca/PublicArtRegistry/"}, {"ord": 3, "city_id": "vancouver", "author_nickname": "\ubc84\ub098\ube44\ud638\uc218", "tag_slug": "life", "title": "\ubc34\ucfe0\ubc84 \ub3c4\uc2dc\uc232\uc5d4 \uae38\uac00 \ub098\ubb34\ub791 \uc0ac\uc720\uc9c0 \ub098\ubb34\ub3c4 \ub4e4\uc5b4\uac00\ub124", "body": "\uc232 \uc598\uae30 \ub098\uc624\uba74 \uba40\ub9ac \uac08 \uc0dd\uac01\ubd80\ud130 \ud588\ub294\ub370 \ub0b4 \uc0c1\uc0c1\ub9cc \uc7a5\uac70\ub9ac\uc600\ub124 \u314b\u314b \ub450 \uac00\uc9c0\ub9cc \uc801\uc5b4\ub460\n1) \ubc34\ucfe0\ubc84 \ub3c4\uc2dc\uc232\uc740 \uacf5\uc6d0\u00b7\uac00\ub85c\uc218\u00b7\uc0ac\uc720\uc9c0\uc5d0 \uc788\ub294 \ub098\ubb34\uae4c\uc9c0 \ud3ec\ud568\ud558\ub294 \ub9d0\uc774\uc57c\n2) \uadf8 \ub098\ubb34\ub4e4\uc774 \uadf8\ub298\uc774\ub791 \ub3d9\ubb3c \uc11c\uc2dd\uc9c0\ub3c4 \ub9cc\ub4e4\uc5b4\uc8fc\ub2c8, \uc774\ubc88\uc5d4 \uac00\uae4c\uc6b4 \uae38\uac00 \ub098\ubb34\ubd80\ud130 \ub208\uc5ec\uaca8\ubcf4\ub824\uace0", "source": "https://vancouver.ca/parks-recreation-culture/urban-forest-strategy.aspx"}, {"ord": 4, "city_id": "vancouver", "author_nickname": "\ub3c4\uc11c\uad00\ub2e8\uace8", "tag_slug": "education", "title": "VPL \ud070\uae00\uc790\ucc45\uc774\ub791 \uc74c\uc131\ud574\uc124 \uc601\uc0c1\ub3c4 \uc54c\uc544\ub450\ub294 \uc911", "body": "\ucc45\uc744 \uc77d\ub294 \ubc29\uc2dd\uc740 \uc885\uc774\ucc45 \ud55c \uad8c\uc774\uba74 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud558\ub358 \ub54c\uac00 \uc788\uc5c8\ub294\ub370\nVPL\uc5d0\ub294 \ud070\uae00\uc790\ucc45\ub3c4 \ub530\ub85c \uc788\uace0\n\uc624\ub514\uc624\ubd81\ub3c4 CD\u00b7MP3 CD\u00b7\ub2e4\uc6b4\ub85c\ub4dc \uac19\uc740 \ud615\uc2dd\uc73c\ub85c \ub098\ub258\uc5b4 \uc788\ub124\n\uc601\ud654\ub098 TV \ud504\ub85c\uadf8\ub7a8\uc740 \uc74c\uc131\ud574\uc124\uc774 \uc788\ub294 DVD\u00b7\ube14\ub8e8\ub808\uc774 \uc790\ub8cc\ub3c4 \uc788\uc5b4\n\ub098\ub294 \ubb58 \uc77d\uc744\uc9c0\ub9cc\ud07c \uc5b4\ub5a4 \ubc29\uc2dd\uc774 \ud3b8\ud55c\uc9c0\ub3c4 \uc880 \ub354 \uc0dd\uac01\ud574\ubcf4\ub824\ub294 \uc911", "source": "https://www.vpl.ca/borrowing/collections/accessible"}, {"ord": 5, "city_id": "vancouver", "author_nickname": "\uc2a4\uce74\uc774\ud2b8\ub808\uc778\ud1b5\uadfc", "tag_slug": "transport", "title": "\ubc34\ucfe0\ubc84 \uadf8\ub9b0\uc6e8\uc774\ub294 \uc790\uc804\uac70\ub9cc \ud0c0\ub294 \uae38\uc774 \uc544\ub2c8\ub124", "body": "\uac77\ub294 \uc0ac\ub78c, \uc790\uc804\uac70 \ud0c0\ub294 \uc0ac\ub78c, \ud720\uccb4\uc5b4\ub85c \uc6c0\uc9c1\uc774\ub294 \uc0ac\ub78c\uc740 \uac19\uc740 \ub3d9\ub124\uc5d0\uc11c\ub3c4 \ud544\uc694\ud55c \uae38\uc774 \ub2e4\ub984\n\ubc34\ucfe0\ubc84 \uadf8\ub9b0\uc6e8\uc774\ub294 \uac77\uae30\u00b7\uc790\uc804\uac70\u00b7\ubc14\ud034 \uc774\ub3d9\uc744 \uc704\ud55c \uad50\ud1b5 \uc5f0\uacb0\ub9dd\uc774\uc57c\n\ucc28 \ud1b5\ud589\uc744 \uc904\uc774\uac70\ub098 \ucc28\uac00 \uc5c6\ub294 \uad6c\uac04\uc73c\ub85c \uacf5\uacf5 \uacf5\uac04\uacfc \uc790\uc5f0 \uacf5\uac04\uc744 \uc774\uc5b4\n\ubb3c\uac00 \uc0b0\ucc45\uae38\ubfd0 \uc544\ub2c8\ub77c \ub3d9\ub124 \uac70\ub9ac\ub098 \uc790\uc5f0 \uc0b0\ucc45\ub85c\ub3c4 \uc5ec\uae30\uc5d0 \ub4e4\uc5b4\uac00\uace0\n\ub09c \ud658\uc2b9\uc5ed\ub9cc \ucc0d\ub358 \uc9c0\ub3c4\uc5d0 \uac78\uc5b4\uc11c \uc774\uc5b4\uac08 \uae38\ub3c4 \uac19\uc774 \ub123\uc744 \uac70\uc57c", "source": "https://vancouver.ca/streets-transportation/greenways-for-walking-and-cycling.aspx"}, {"ord": 6, "city_id": "toronto", "author_nickname": "\ud1a0\ub860\ud1a0\ud559\ubd80\ubaa8", "tag_slug": "life", "title": "\uae38\ub4dc\ud30c\ud06c\uc5d4 \uc61b \uac74\ubb3c\uc758 \uc870\uac01\ub4e4\ub3c4 \ubaa8\uc5ec \uc788\ub124", "body": "\uc624\ub798\ub41c \uac74\ubb3c\uc740 \ud1b5\uc9f8\ub85c \ub0a8\uc544\uc57c \ubcfc \uc218 \uc788\ub294 \uc904 \uc54c\uc558\ub294\ub370, \uae38\ub4dc\ud30c\ud06c\uc564\uac00\ub4e0\uc2a4\uc5d4 \uacf5\uacf5\ubbf8\uc220\uc774\ub791 \uac74\ucd95 \uc870\uac01\ub4e4\uc774 \ud568\uaed8 \uc788\uc74c\n\uc2a4\uce74\ubcf4\ub85c \ube14\ub7ec\ud504 \uc704 \uc232\uacfc \uc815\uc6d0\uc5d0 \uc774\ub7f0 \ud754\uc801\ub3c4 \ub0a8\uc544 \uc788\ub2e4\ub2c8, \uc0b0\ucc45 \ud6c4\ubcf4\uc5d0 \ub123\uc744 \uac70\uc57c (\ub0b4 \uc5ed\uc0ac \uacf5\ubd80\ub3c4 \ub2e4\ub9ac\ub85c \uc880 \ud574\uc57c\uaca0\ub124 \u314b\u314b)", "source": "https://www.toronto.ca/explore-enjoy/parks-recreation/places-spaces/beaches-gardens-attractions/gardens-and-horticulture/public-gardens/feature-garden-parks/"}, {"ord": 7, "city_id": "toronto", "author_nickname": "\uc11c\ube44\uc2a4\uc628\ud0c0\ub9ac\uc624", "tag_slug": "transport", "title": "\ubc24 TTC \ubc84\uc2a4\uc5d0\uc120 \uc815\ub958\uc7a5 \uc0ac\uc774 \ud558\ucc28\ub97c \uc694\uccad\ud560 \uc218\ub3c4 \uc788\ub124", "body": "\ubc24\uc5d0 \ud63c\uc790 \ubc84\uc2a4\uc5d0\uc11c \ub0b4\ub9ac\ub294 \uc0ac\ub78c\uc740 \ub0b4\ub824\uc11c \uac77\ub294 \uae38\ub3c4 \uc2e0\uacbd \uc4f0\uaca0\ub124, \ub09c \ub178\uc120\ub9cc \uc0dd\uac01\ud588\uc74c\nTTC\ub294 \ubc24 9\uc2dc\ubd80\ud130 \uc0c8\ubcbd 5\uc2dc\uae4c\uc9c0 \ud63c\uc790 \ubc84\uc2a4\ub97c \ud0c0\uba70 \ubd88\uc548\uc744 \ub290\ub07c\ub294 \uc2b9\uac1d\uc774 \uc815\ub958\uc7a5 \uc0ac\uc774 \ud558\ucc28\ub97c \uc694\uccad\ud560 \uc218 \uc788\uc5b4, \uae30\uc0ac\uac00 \uc548\uc804\ud558\uac8c \uc124 \uc218 \uc788\uc5b4\uc57c \ud558\uace0 \uc804\ucc28\uc5d4 \uc801\uc6a9 \uc548 \ub428\n\uc774\uc6a9 \uc808\ucc28\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \ub2e4\uc2dc \ud655\uc778\ud558\ub824\uace0, \uac19\uc774 \uadc0\uac00\ud560 \ub550 \ub0b4\ub824\uc11c \uac77\ub294 \uae38 \uc598\uae30\ub3c4 \ud574\ubcfc\uae4c \ud574", "source": "https://www.ttc.ca/accessibility/Easier-access-on-the-TTC/Riding-the-Bus"}, {"ord": 8, "city_id": "toronto", "author_nickname": "\uc758\uacac\uc788\ub294\uc0ac\ub78c", "tag_slug": "life", "title": "\ud1a0\ub860\ud1a0 \ubba4\uc9c1\uac00\ub4e0\uc740 \ubc14\ud750 \uc74c\uc545\uc744 \uc815\uc6d0\uc73c\ub85c \uc62e\uae34 \uac70\ub124", "body": "\ud1a0\ub860\ud1a0 \ubba4\uc9c1\uac00\ub4e0 \ucc98\uc74c \uc54c\uc544\ubcf4\ub294\ub370 \uc774\ub984\ub9cc \ubcf4\uace0 \uc74c\uc545 \ud2c0\uc5b4\ub193\ub294 \uacf5\uc6d0\uc778 \uc904 \ud63c\uc790 \uc0c1\uc0c1\ud568 \u314b\u314b\n\uc5ec\uae34 \uccbc\ub9ac\uc2a4\ud2b8 \uc694\uc694\ub9c8\uc5d0\uac8c\uc11c \uc601\uac10\uc744 \ubc1b\uc544 \ubc14\ud750 \ubaa8\uc74c\uace1\uc744 \uc2dd\ubb3c\uacfc \uc815\uc6d0 \uc694\uc18c\ub85c \ud45c\ud604\ud55c \uacf5\uac04\uc774\uc57c\n\uc74c\uc545\uc744 \ub4e3\ub294 \uac83 \ub9d0\uace0 \ud48d\uacbd\uc73c\ub85c \ud480\uc5b4\ub0b8\ub2e4\ub294 \uac8c \uc2e0\uae30\ud574\uc11c, \ub3d9\ub124 \uc774\ub984 \uc678\uc6b0\ub294 \uc7ac\ubbf8\uac00 \ud558\ub098 \ub298\uc5c8\uc74c", "source": "https://www.toronto.ca/explore-enjoy/parks-recreation/places-spaces/beaches-gardens-attractions/gardens-and-horticulture/public-gardens/"}, {"ord": 9, "city_id": "toronto", "author_nickname": "\ud1a0\ub860\ud1a0\ub3c4\uc11c\uad00", "tag_slug": "education", "title": "TPL \uc5b8\uc5b4\ud559\uc2b5 \ubaa9\ub85d\uc5d4 \ub9dd\uace0\ub7ad\uadc0\uc9c0\ub3c4 \uc788\ub124", "body": "\uc601\uc5b4 \uacf5\ubd80 \ub2e4\uc2dc \uc0dd\uac01\ud558\uba74 \uc5b4\ub514\uc11c\ubd80\ud130 \ud574\uc57c \ud560\uc9c0 \uc880 \ub9c9\ub9c9\ud568\nTPL \uc5b8\uc5b4\ud559\uc2b5 \uc790\ub8cc \ubaa9\ub85d\uc5d0 \ub9dd\uace0\ub7ad\uadc0\uc9c0\ub3c4 \uc788\ub124\n\uc0c8 \uc5b8\uc5b4\ub97c \ubc30\uc6b0\uac70\ub098 \uc601\uc5b4\ub97c \uc775\ud788\ub294 \ub370 \uc4f0\ub294 \uc628\ub77c\uc778 \uc790\ub8cc\uc57c\n\ub2f9\uc7a5 \uacc4\ud68d\uc744 \ud06c\uac8c \uc7a1\uae30\ubcf4\ub2e8 \ub0b4\uac00 \ud3b8\ud558\uac8c \ubcfc \uc218 \uc788\ub294 \ubc29\uc2dd\uc778\uc9c0\ubd80\ud130 \uc0dd\uac01\ud574\ubcf4\ub824\ub294 \uc911\n\uc5b8\uc5b4 \uacf5\ubd80 \ub2e4\uc2dc \uc2dc\uc791\ud560 \ub54c\ub294 \uc775\uc219\ud55c \ud45c\ud604\ubd80\ud130 \ubcf4\ub294 \uac8c \ub35c \ubd80\ub2f4\uc2a4\ub7ec\uc6e0\uc5b4?", "source": "https://tpl.ca/resources/language-learning/"}, {"ord": 10, "city_id": "toronto", "author_nickname": "\ubcbd\ub3cc\uace8\ubaa9\ube5b", "tag_slug": "life", "title": "TPL \ub179\uc74c \uacf5\uac04\uc5d4 \uce74\uba54\ub77c\ub791 \uadf8\ub9b0\uc2a4\ud06c\ub9b0\ub3c4 \uc788\ub124", "body": "\ub179\uc74c \ud558\ub098 \ud574\ubcfc\uae4c \uc0dd\uac01\ud558\uba74 \uc7a5\ube44\ubd80\ud130 \uc54c\uc544\ubd10\uc57c \ud560 \uac83 \uac19\uc544\uc11c \uc880 \ubd80\ub2f4\uc2a4\ub7ec\uc6e0\uc74c\nTPL \uc624\ub514\uc624\ube44\uc8fc\uc5bc \uc2a4\ud29c\ub514\uc624\uc5d0\uc11c \ub2e4\ub8e8\ub294 \uac83\ub4e4\uc744 \uc801\uc5b4\ub460\n1) \ub9c8\uc774\ud06c\u00b7\uc624\ub514\uc624 \uc778\ud130\ud398\uc774\uc2a4 \uac19\uc740 \uc18c\ub9ac \uc7a5\ube44\n2) \uc601\uc0c1 \uce74\uba54\ub77c\u00b7\uc870\uba85\u00b7\uadf8\ub9b0\uc2a4\ud06c\ub9b0 \uac19\uc740 \uc601\uc0c1 \uc7a5\ube44\n\ubd84\uad00\ub9c8\ub2e4 \uc7a5\ube44\uac00 \ub2ec\ub77c\uc11c, \ub098\ub294 \ubb58 \ub9cc\ub4e4\uc5b4\ubcf4\uace0 \uc2f6\uc740\uc9c0\ubd80\ud130 \uc791\uac8c \uace8\ub77c\ubcfc \uac70\uc57c", "source": "https://tpl.ca/using-the-library/computer-services/digital-innovation-services/recording-studios/"}, {"ord": 11, "city_id": "montreal", "author_nickname": "\uc6b0\ud3b8\ubc88\ud638\uc218\ucca9", "tag_slug": "life", "title": "\ubc14\uc774\uc624\ub3d4\uc740 \ub3d9\ubb3c\uacfc \uc11c\uc2dd \ud658\uacbd\uc744 \uac19\uc774 \ubcf4\ub294 \uacf5\uac04\uc774\ub124", "body": "\ub3d9\ubb3c \ubcf4\ub7ec \uac00\ub294 \uc0ac\ub78c\ub3c4 \uadf8 \ub3d9\ubb3c\uc774 \uc0ac\ub294 \ud658\uacbd\uae4c\uc9c0 \uac19\uc774 \ub9cc\ub098\uaca0\ub124, \ubc14\uc774\uc624\ub3d4\uc5d4 \uc544\uba54\ub9ac\uce74 \uc0dd\ud0dc\uacc4 \ub2e4\uc12f \uacf3\uc774 \ud55c \uc9c0\ubd95 \uc544\ub798 \uc788\uc5b4\n\ub09c \ub3d9\ubb3c \uc774\ub984 \uc678\uc6b0\ub294 \ub370\uc11c \ub05d\ub0b4\uc9c0 \ub9d0\uace0 \uc0ac\ub294 \ud48d\uacbd\ub3c4 \uac19\uc774 \uae30\uc5b5\ud560\ub798 (\uba38\ub9bf\uc18d\uc5d4 \uc790\uafb8 \ub3d9\ubb3c \uc5bc\uad74\ub9cc \ub0a8\uc74c \u314b\u314b)", "source": "https://www.mtl.org/en/what-to-do/activities/biodome-de-montreal"}, {"ord": 12, "city_id": "montreal", "author_nickname": "\uc7a5\ud0c8\ub871\ubc14\uad6c\ub2c8", "tag_slug": "life", "title": "\ud478\uc575\ud0c0\uce7c\ub9ac\uc5d0 \ubc15\ubb3c\uad00\uc740 \ub3c4\uc2dc\uac00 \uc2dc\uc791\ub41c \ud130 \uc704\uc5d0 \uc788\ub124", "body": "\ub3c4\uc2dc \uc5ed\uc0ac\ub294 \uc608\uc804\ubd80\ud130 \uc624\ub798\ub41c \uac74\ubb3c \ucabd\ub9cc \uc0dd\uac01\ud588\ub294\ub370, \ud478\uc575\ud0c0\uce7c\ub9ac\uc5d0 \uace0\uace0\ud559\u00b7\uc5ed\uc0ac \ubc15\ubb3c\uad00\uc740 \ubaac\ud2b8\ub9ac\uc62c\uc774 \uc2dc\uc791\ub41c \ud130 \uc704\uc5d0 \uc788\ub124\n\uadf8 \uc790\ub9ac\uc758 \uc61b \ud754\uc801\uc744 \ub0a8\uaca8 \ubcf4\uc5ec\uc8fc\ub294 \uacf3\uc774\ub77c\ub2c8 \uc880 \uc124\ub818, \ub2e4\uc74c\uc5d4 \uac19\uc774 \ub3c4\uc2dc\uc758 \ub545\uc18d \uc774\uc57c\uae30\ubd80\ud130 \uc54c\uc544\ubcf4\uba74 \uc88b\uc744 \ub4ef", "source": "https://montreal.ca/en/articles/archaeological-sites-21773"}, {"ord": 13, "city_id": "montreal", "author_nickname": "\uc62c\ub4dc\ud3ec\ud2b8\ubc14\ub78c", "tag_slug": "life", "title": "\ucea1\uc0dd\uc790\ud06c \ub18d\uc7a5, \uc9c0\uae08\uc740 \ub3d9\ubb3c \uc5c6\uc774 \uc0b0\ucc45\uae38\uc774 \ub0a8\uc544 \uc788\ub124", "body": "\ub18d\uc7a5\uc774\ub77c\uace0 \ud558\uba74 \uc608\uc804\ubd80\ud130 \ub3d9\ubb3c \uad6c\uacbd\ubd80\ud130 \ub5a0\uc62c\ub838\ub294\ub370, \ucea1\uc0dd\uc790\ud06c \uc0dd\ud0dc\ub18d\uc7a5\uc5d4 \uc9c0\uae08 \ub3d9\ubb3c\uc774 \uc5c6\ub124\n\ub18d\uc7a5 \uc8fc\ubcc0 \uc57c\uc678 \uacf5\uac04\uc774\ub791 \uc0b0\ucc45\uae38\uc740 \ub0a8\uc544 \uc788\uace0, \ud5db\uac04 \uc548\uc740 \ub4e4\uc5b4\uac08 \uc218 \uc5c6\ub294 \uc0c1\ud0dc\ub798\n\uc6b4\uc601 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \ub098\ub4e4\uc774 \uc804\uc5d0 \ub2e4\uc2dc \ud655\uc778\ud558\ub824\uace0, \ub09c \ub3d9\ubb3c \uad6c\uacbd\ubcf4\ub2e4 \uadf8 \uc8fc\ubcc0 \uae38 \uc54c\uc544\ubcf4\ub294 \ucabd\uc73c\ub85c \uc0dd\uac01\ud560\ub798", "source": "https://montreal.ca/en/places/cap-saint-jacques-ecological-farm-and-general-store"}, {"ord": 14, "city_id": "montreal", "author_nickname": "\ubd88\uc5b4\ucc45\uac08\ud53c", "tag_slug": "transport", "title": "\uc544\uc950\ub974 \uba54\ud2b8\ub85c\ub294 \uac1d\ucc28 \uc0ac\uc774\uac00 \ucb49 \uc774\uc5b4\uc9c0\ub294 \uad6c\uc870\ub124", "body": "\uc5f4\ucc28\ub294 \uce78\ub9c8\ub2e4 \ub530\ub85c \ub5a8\uc5b4\uc838 \uc788\ub2e4\uace0\ub9cc \uc0dd\uac01\ud55c \ub0b4\uac00 \ub108\ubb34 \ub2e8\uc21c\ud588\ub098 \ubd04\n\ubaac\ud2b8\ub9ac\uc62c \uc544\uc950\ub974 \uc5f4\ucc28\ub294 \uac1d\ucc28 \uc0ac\uc774\uac00 \uc774\uc5b4\uc838\uc11c \ud55c\ucabd \ub05d\ubd80\ud130 \ub2e4\ub978 \ub05d\uae4c\uc9c0 \uc774\ub3d9\ud560 \uc218 \uc788\uc5b4\n\uc190\uc7a1\uc774 \uc704\uce58\ub791 \uc0c9 \ub300\ube44\ub3c4 \uc811\uadfc\uc131\uc744 \uc0dd\uac01\ud574\uc11c \uc124\uacc4\ud55c \uac70\uace0\n\ub178\uc120\ub3c4\ub9cc \uc678\uc6b0\uba74 \uba54\ud2b8\ub85c\ub97c \ub2e4 \uc54c \uc904 \uc54c\uc558\ub294\ub370 \uc774\ubc88\uc5d4 \uc190\uc7a1\uc774 \uacf5\ubd80\uae4c\uc9c0 \ub298\uc5b4\ub0a8 \u314b\u314b\n\ub09c \ub2f9\uc7a5 \ub2e4 \uae30\uc5b5\ud558\uae34 \uc5b4\ub835\uace0 \ub0b4\ubd80 \uad6c\uc870 \ud558\ub098\ubd80\ud130 \uc775\ud600\ubcfc\uae4c \ud558\ub294 \uc911", "source": "https://www.stm.info/fr/node/635"}, {"ord": 15, "city_id": "montreal", "author_nickname": "\ubabd\ub8e8\uc544\uc584\uc78e\uc0c8", "tag_slug": "life", "title": "\ubaac\ud2b8\ub9ac\uc62c \ud50c\ub77c\ub124\ud0c0\ub9ac\uc6c0\uc740 \ub3d4 \uc601\uc0c1\uc73c\ub85c \uc6b0\uc8fc\ub97c \ubcf4\ub294 \uacf3\uc774\ub124", "body": "\uc6b0\uc8fc \uc598\uae30\ub294 \uad81\uae08\ud55c\ub370 \uba40\ub9ac \uc788\ub294 \ucc9c\uccb4\ub97c \uba38\ub9bf\uc18d\uc73c\ub85c \uadf8\ub9ac\uae30\ub294 \uc5b4\ub824\uc6cc\uc11c \uc54c\uc544\ubcf4\ub294 \uc911\n\ubaac\ud2b8\ub9ac\uc62c \ud50c\ub77c\ub124\ud0c0\ub9ac\uc6c0\uc740 \ub3d4\uc744 \uc4f0\ub294 \ubab0\uc785\ud615 \uc601\uc0c1 \uacf5\uac04\uc774\uc57c\n\uc6b0\uc8fc\ub97c \ub2e4\ub8e8\ub294 \uc0c1\uc601\uacfc \uc804\uc2dc\ub85c \ucc9c\ubb38\ud559\uc744 \uc54c\ub9ac\ub294 \uacf3\uc774\uace0\n\ub098\ub294 \uc6b0\uc8fc \uc804\uccb4\ub97c \ud55c\uaebc\ubc88\uc5d0 \uc678\uc6b0\uae30\ubcf4\ub2e4 \uad00\uc2ec \uac00\ub294 \ucc9c\uccb4 \ud558\ub098\ubd80\ud130 \ubcfc \uac70\uc57c\n\uc774\ub7f0 \uc601\uc0c1 \ubcfc \ub54c\ub294 \ubcc4\uc790\ub9ac\ub791 \ud589\uc131 \uc911 \uc5b4\ub290 \ucabd\uc774 \ub354 \uad81\uae08\ud574?", "source": "https://www.mtl.org/en/what-to-do/culture-arts-heritage/planetarium-de-montreal"}, {"ord": 16, "city_id": "edmonton", "author_nickname": "\uc0ac\uc6b0\uc2a4\uac8c\uc774\ud2b8\uc810\uc2ec", "tag_slug": "transport", "title": "ETS \ubc84\uc2a4 \uc785\uad6c\ub294 \ub0ae\uc544\uc9c0\ub294 \uae30\ub2a5\ub3c4 \uc788\ub124", "body": "1) ETS \ubc84\uc2a4\uc5d4 \uc55e\ucabd \uc785\uad6c\ub97c \ub0ae\ucd94\ub294 \ub2c8\ub9c1 \uae30\ub2a5\uc774 \uc788\uc74c\n2) \uacbd\uc0ac\ub85c\uc640 \uc6b0\uc120 \uc88c\uc11d\ub3c4 \uac16\ucd98 \uad6c\uc870\ub77c, \ub09c \ud0c0\ub294 \ubb38 \uc8fc\ubcc0\ubd80\ud130 \uc880 \ub354 \ub208\uc5ec\uaca8\ubcf4\ub824\ub294 \uc911", "source": "https://www.edmonton.ca/ets/accessibility"}, {"ord": 17, "city_id": "edmonton", "author_nickname": "\ub3d9\ubb3c\uadf8\ub9bc\uc218\ucca9", "tag_slug": "life", "title": "\ub8e8\uc774\uc2a4\ub9e4\ud0a4\ub2c8 \uac15\ubcc0\uacf5\uc6d0\uc5d4 \uc911\uad6d\uc2dd \uc815\uc790\ub3c4 \uc788\ub124", "body": "\uac15\ubcc0 \uac77\ub294 \uc0ac\ub78c \uacc1\uc5d0 \uc26c\ub294 \ubaa8\uc591\ub3c4 \uc5ec\ub7ec \uac00\uc9c0\ub124, \ub8e8\uc774\uc2a4\ub9e4\ud0a4\ub2c8 \ub9ac\ubc84\ud504\ub7f0\ud2b8 \uacf5\uc6d0\uc5d4 \uc911\uad6d\uc2dd \uc815\uc6d0\uacfc \uc815\uc790\uac00 \uc788\uc5b4\n\uc608\uc804\uc5d4 \uac15\ubcc0\uc740 \uae38 \ud558\ub098 \uae38\uac8c \uc774\uc5b4\uc9c4 \ubaa8\uc2b5\ub9cc \ub5a0\uc62c\ub838\ub294\ub370 \ub0b4 \uc0c1\uc0c1\ub825\uc774 \ub108\ubb34 \uc9c1\uc120\uc774\uc5c8\uad70 \u314b\u314b", "source": "https://www.edmonton.ca/activities_parks_recreation/parks_rivervalley/louise-mckinney-riverfront-park"}, {"ord": 18, "city_id": "edmonton", "author_nickname": "\uc81c\uc2a4\ud37c\uc560\ube44\ub274", "tag_slug": "life", "title": "\uc54c\ubc84\ud0c0 \uc758\ud68c \ud68c\uc758\uc7a5\uc5d4 \uc2a4\ud14c\uc778\ub4dc\uae00\ub77c\uc2a4 \ucc9c\uc7a5\ub3c4 \uc788\ub124", "body": "\ud68c\uc758\uc2e4\uc744 \uadf8\ub0e5 \ucc45\uc0c1 \ubaa8\uc778 \ubc29\uc73c\ub85c \uc0dd\uac01\ud55c \ub0b4\uac00 \ub108\ubb34 \ub2e8\uc21c\ud588\ub098 \ubd04\n\uc54c\ubc84\ud0c0 \uc758\ud68c \ud68c\uc758\uc7a5\uc5d0\ub294 \uc2a4\ud14c\uc778\ub4dc\uae00\ub77c\uc2a4\ub97c \ub123\uc740 \uaca9\uc790 \ucc9c\uc7a5, \ub300\ub9ac\uc11d \uc7a5\uc2dd, \ub9c8\ud638\uac00\ub2c8 \ubaa9\uc7ac \ubcbd\uc774 \uc788\uc5b4\n\uc0ac\ub78c\ub4e4\uc774 \ud1a0\ub860\ud558\ub294 \uacf5\uac04\ub3c4 \uac74\ubb3c \ub514\ud14c\uc77c\uc774 \uc774\ub807\uac8c \ub9ce\ub2e4\ub2c8, \ub09c \uc5b4\ub514\ubd80\ud130 \ub208\uc5ec\uaca8\ubcfc\uc9c0\ub294 \uc544\uc9c1 \ubabb \uace0\ub974\uaca0\uc5b4", "source": "https://www.assembly.ab.ca/learn/the-legislative-assembly/chamber"}, {"ord": 19, "city_id": "edmonton", "author_nickname": "\uc5d0\ub4dc\uba3c\ud2bc\uaca8\uc6b8", "tag_slug": "life", "title": "ETS \ubd84\uc2e4\ubb3c \ubb38\uc758\ud560 \ub550 \ubb3c\uac74 \ubaa8\uc591\ub3c4 \uaf64 \uc790\uc138\ud788 \uc801\ub124", "body": "\ubc84\uc2a4\uc5d0 \ubb3c\uac74 \ub450\uace0 \ub0b4\ub9ac\uba74 \uc783\uc5b4\ubc84\ub9b0 \uc7a5\uc18c\ub9cc \ub5a0\uc62c\ub9b4 \uac83 \uac19\uc740\ub370\nETS \ubd84\uc2e4\ubb3c \ubb38\uc758\ub294 \ubc84\uc2a4\u00b7LRT \uac19\uc740 \uad50\ud1b5\ud3b8 \uc885\ub958\ub791 \ub178\uc120\u00b7\uc5ed \uc704\uce58, \ubb3c\uac74 \uc0c9\u00b7\uc7ac\uc9c8\u00b7\ub0b4\uc6a9\ubb3c\ub3c4 \uc801\ub294 \ubc29\uc2dd\uc784\n\uc811\uc218 \uc808\ucc28\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \uc2e4\uc81c \ubb38\uc758 \uc804\uc5d4 \ub2e4\uc2dc \ud655\uc778\ud558\ub824\uace0", "source": "https://www.edmonton.ca/ets/lost-and-found"}, {"ord": 20, "city_id": "edmonton", "author_nickname": "\ud5e8\ub370\uc774\ud558\uc774\uc6e8\uc774", "tag_slug": "life", "title": "\ubc00\ub108\ub3c4\uc11c\uad00\uc5d4 \uc6d0\uc8fc\ubbfc \uc758\ub840\uc640 \ubaa8\uc784\uc744 \uc704\ud55c \uacf5\uac04\ub3c4 \uc788\ub124", "body": "\ucc98\uc74c\uc5d4 \ub3c4\uc11c\uad00\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc774\ub294 \uacf5\uac04\uc774\uba74 \uadf8\ub0e5 \ud68c\uc758\uc2e4\uc744 \ub5a0\uc62c\ub838\uc74c\n\ubc00\ub108\ub3c4\uc11c\uad00\uc758 \uc120\ub354\ubc84\ub4dc\ud558\uc6b0\uc2a4\ub294 \uc6d0\uc8fc\ubbfc \uc758\ub840\uc640 \ubaa8\uc784\uc744 \uc704\ud574 \ub9cc\ub4e0 \uc804\uc6a9 \uacf5\uac04\uc774\ub124\n\ud06c\ub9ac \uc6d0\ub85c\uc640 \uacf5\ub3d9\uccb4\uac00 \uc124\uacc4\uc5d0 \ud568\uaed8\ud588\uace0, \ubc14\ub2e5\u00b7\ubcbd\u00b7\ucc9c\uc7a5\uc5d0\ub3c4 \ud3ec\ud50c\ub7ec \ub098\ubb34\ub97c \uc37c\ub300\n\uc6d0\uc8fc\ubbfc\uacfc \ube44\uc6d0\uc8fc\ubbfc \ubaa8\ub450 \ubc30\uc6b0\uace0 \ud568\uaed8\ud560 \uc218 \uc788\ub294 \uacf5\uac04\uc73c\ub85c \uc6b4\uc601\ub418\ub294 \uac70\uc57c\n\ub3d9\ub124 \uc54c\uc544\uac00\ub294 \uae40\uc5d0 \uc774\ub7f0 \uacf3\ub3c4 \uae30\uc5b5\ud574\ub458\ub798, \uac19\uc774 \ub3c4\uc11c\uad00 \uc598\uae30\ud560 \ub54c \ub0b4 \uc124\uba85\uc774 \ucc45\uc7a5 \ud558\ub098\uc5d0\uc11c \uc880 \ubc97\uc5b4\ub098\uaca0\ub124 \u314b\u314b", "source": "https://www.epl.ca/milner-library/thunderbird-house/"}, {"ord": 21, "city_id": "calgary", "author_nickname": "\ub178\uc2a4\ud790\uc7a5\ubcf4\uae30", "tag_slug": "life", "title": "\uc6e8\uc2a4\ud2b8\ub178\uc988\ud06c\ub9ac\ud06c \uc2a4\ud50c\ub9bf\ub85d\uc740 \ube59\ud558\uac00 \ub0a8\uae34 \ubc14\uc704\ub124", "body": "\uc2a4\ud50c\ub9bf\ub85d\uc774\ub780 \uc774\ub984 \ucc98\uc74c \uc54c\uc544\ubcf4\ub294\ub370 \uc6e8\uc2a4\ud2b8\ub178\uc988\ud06c\ub9ac\ud06c \uacf5\uc6d0\uc5d0 \uc788\ub294 \ube59\ud558 \uc720\ub798\uc758 \ubc14\uc704\ub124\n\uacf5\uc6d0\uc5d0 \uc624\ub798\ub41c \ucc44\uc11d\uc7a5 \ud754\uc801\ub3c4 \uc788\ub2e4\ub2c8 \uac19\uc774 \uac78\uc73c\uba70 \ubcfc \uac8c \ub354 \uc788\uaca0\ub294\ub370, \uc5b8\uc81c \uac08\uc9c0\ub294 \uc544\uc9c1 \ubabb \uc815\ud588\uc74c", "source": "https://www.calgary.ca/parks/west-nose-creek-park.html"}, {"ord": 22, "city_id": "calgary", "author_nickname": "\ud504\ub9b0\uc2a4\uc544\uc77c\ub79c\ub4dc", "tag_slug": "education", "title": "\ubcf4\ub124\uc2a4\ud30c\ud06c \ub77c\uad70\uc740 \uc5ec\ub984\uacfc \uaca8\uc6b8 \uc4f0\uc784\uc774 \ub2e4\ub974\ub124", "body": "\uc804\uc5d4 \uacf5\uc6d0 \ubb3c\uac00\uba74 \ubcf4\ud2b8 \ud48d\uacbd\ub9cc \ub5a0\uc62c\ub838\ub294\ub370, \ubcf4\ub124\uc2a4\ud30c\ud06c\uc758 \uc595\uc740 \ub77c\uad70\uc740 \uc5ec\ub984 \ubcf4\ud2b8\uc640 \uaca8\uc6b8 \uc2a4\ucf00\uc774\ud2b8 \uacf5\uac04\uc73c\ub85c \uc4f0\uc784\n\uc9c0\uae08\uc774 \ub450 \uacc4\uc808 \uc0ac\uc774\ub77c\ub294 \uac78 \ub0b4 \uc0c1\uc0c1\ub9cc \uc790\uafb8 \uac74\ub108\ub700 \u314b\u314b \uc5b4\ub290 \ub54c \uac00\ubcfc\uc9c0\ub294 \uc544\uc9c1 \ubabb \uace8\ub790\uc5b4", "source": "https://www.calgary.ca/parks/bowness-park-features.html"}, {"ord": 23, "city_id": "calgary", "author_nickname": "C\ud2b8\ub808\uc778\ud1b5\uadfc", "tag_slug": "transport", "title": "\uce98\uac70\ub9ac Transit \uc571\uc740 \uacbd\ub85c \uacc4\ud68d\uc774\ub791 \uc774\ub3d9 \ucd94\uc801\uc744 \uac19\uc774 \ud558\ub124", "body": "\uae30\ub2e4\ub9ac\ub294 \ubc84\uc2a4\uac00 \uc5b4\ub514\ucbe4\uc778\uc9c0 \uc54c\uba74 \uc2dc\uac04\ud45c \uc22b\uc790\ub9cc \ubcf4\ub294 \uac83\ubcf4\ub2e4 \ub35c \ub9c9\ub9c9\ud560 \ub4ef\n\uce98\uac70\ub9ac Transit \uc571\uc740 \uc2e4\uc2dc\uac04 \uacbd\ub85c \uacc4\ud68d\uc774\ub791 \ud0c0\ub824\ub294 \uad50\ud1b5\ud3b8 \ucd94\uc801\uc744 \uac19\uc774 \ub2e4\ub8e8\ub124\n\uc774\uc6a9 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \uc4f0\uae30 \uc804\uc5d0 \ub2e4\uc2dc \ud655\uc778\ud558\ub824\uace0, \uc774\ub7f0 \uc571 \ubcfc \ub54c \ub3c4\ucc29 \uc608\uc0c1\uc774\ub791 \uacbd\ub85c \uc911 \ubb58 \uba3c\uc800 \ubd10?", "source": "https://www.calgarytransit.com/rider-information/rider-tools.html"}, {"ord": 24, "city_id": "calgary", "author_nickname": "\ucee8\ud398\ub354\ub808\uc774\uc158\uacf5\uc6d0", "tag_slug": "life", "title": "\uce98\uac70\ub9ac \ub3c4\uc11c\uad00 \uadf8\ub9bc\ucc45\uc740 \uc5ec\ub7ec \uc5b8\uc5b4\ub85c \ub4e3\ub294 \uc790\ub8cc\ub3c4 \uc788\ub124", "body": "\uadf8\ub9bc\ucc45\uc744 \uc18c\ub9ac \ub0b4 \uc77d\uc73c\ub824\ub2c8 \ub0b4\uac00 \uba3c\uc800 \ubc1c\uc74c \uc5f0\uc2b5\ubd80\ud130 \ud574\uc57c \ud560 \uac83 \uac19\uc74c \u314b\u314b\n\uce98\uac70\ub9ac \ub3c4\uc11c\uad00 LOTE4Kids\ub294 \uc601\uc5b4\u00b7\ud504\ub791\uc2a4\uc5b4\u00b7\uc2a4\ud398\uc778\uc5b4 \uac19\uc740 \uc5ec\ub7ec \uc5b8\uc5b4\uc758 \uadf8\ub9bc\ucc45\uc744 \uc77d\uace0 \ub4e3\ub294 \uc790\ub8cc\ub124\n\uac19\uc774 \ub4e4\uc744 \uc774\uc57c\uae30\ub97c \ud558\ub098 \uace8\ub77c\ubcf4\uace0 \uc2f6\uc740\ub370, \uadf8\ub9bc\ucc45\uc740 \uc775\uc219\ud55c \uc5b8\uc5b4\ub791 \ubc30\uc6b0\ub294 \uc5b8\uc5b4 \uc911 \ubb58\ub85c \ub4e4\uc73c\uba74 \ub354 \uc7ac\ubc0c\uc744\uae4c?", "source": "https://www.calgarylibrary.ca/read-learn-and-explore/digital-library/lote4kids"}, {"ord": 25, "city_id": "calgary", "author_nickname": "\ubcf4\uc6b0\uac15\ubcc0\uc0b0\ucc45", "tag_slug": "life", "title": "\uc0d8\ub9ac\ube59\uc2a4\ud134 \uc591\uc5b4\uc7a5\uc740 \uc1a1\uc5b4\uac00 \ud638\uc218\ub85c \uac00\uae30 \uc804 \uc790\ub77c\ub294 \uacf3\uc774\ub124", "body": "\ubb3c\uace0\uae30\uac00 \ud638\uc218\uc5d0 \uc0ac\ub294 \ubaa8\uc2b5\ub9cc \uc0dd\uac01\ud588\ub294\ub370 \uc790\ub77c\ub294 \uae38\ub3c4 \ub530\ub85c \uc788\ub124\n\ubcf4\uc6b0\ud574\ube44\ud0c0\ud2b8\uc2a4\ud14c\uc774\uc158\uc758 \uc0d8\ub9ac\ube59\uc2a4\ud134 \uc591\uc5b4\uc7a5\uc740 \uc1a1\uc5b4\ub97c \uc54c\uc5d0\uc11c \uc5b4\ub9b0 \ubb3c\uace0\uae30\uae4c\uc9c0 \uae30\ub974\ub294 \uacf3\uc774\uc57c\n\uadf8 \ubb3c\uace0\uae30\ub4e4\uc740 \uc54c\ubc84\ud0c0\uc758 \ud638\uc218\uc640 \uc5f0\ubabb\uc5d0 \ud480\uc5b4\uc8fc\ub294 \uc0ac\uc5c5\uc73c\ub85c \uc774\uc5b4\uc838\n\uc608\uc804\uc5d4 \ubb3c\uace0\uae30 \uc774\ub984\ub9cc \uc678\uc6e0\ub294\ub370 \uc774\ubc88\uc5d4 \ubb3c\uac00\uc5d0 \uc624\uae30 \uc804 \uacfc\uc815\ubd80\ud130 \uae30\uc5b5\ud560 \uac70\uc57c\n\ub0b4 \uc0dd\ud0dc \uacf5\ubd80\uac00 \uc218\uc870 \uc55e\uc5d0\uc11c \ub05d\ub0a0 \uc21c \uc5c6\uc796\uc544 \u314b\u314b", "source": "https://bowhabitat.alberta.ca/visit/fish-hatchery.aspx"}]$CITY$::jsonb)
as x(ord int,city_id text,author_nickname text,tag_slug text,title text,body text,source text)
)
select e.ord,p.id,p.city_id,p.title,p.body,p.author_id,p.status,p.created_at,p.sort_at,p.posted_on,
 p.created_at at time zone 'America/Vancouver' as created_at_vancouver,
 p.created_at at time zone city.timezone as created_at_city,city.timezone,
 pr.city_id as author_city,pr.nickname as author_nickname,
 u.email like '%@seed.gling.invalid' as seed_account,
 p.comment_count,p.view_count,
 p.body=e.body as body_matches,pr.nickname=e.author_nickname as author_matches,
 tag.slug=e.tag_slug as tag_matches,
 (select count(*) from public.posts d where d.city_id=e.city_id and d.title=e.title and d.status='published') as same_city_title_count,
 (select count(*) from public.posts d where d.author_id=p.author_id and d.status='published') as author_published_post_count,
 (select count(*) from public.comments c where c.post_id=p.id and c.deleted_at is null) as actual_comment_count,
 (select count(*) from public.comments c where c.post_id=p.id and c.parent_id is null and c.deleted_at is null) as root_comment_count,
 (select count(*) from public.comments c where c.post_id=p.id and c.parent_id is not null and c.deleted_at is null) as reply_count,
 (select count(*) from public.comments c where c.post_id=p.id and c.parent_id is not null and c.author_id=p.author_id and c.deleted_at is null) as author_reply_count,
 (select count(*) from public.post_views v where v.post_id=p.id) as real_post_view_rows,
 (select jsonb_agg(jsonb_build_object('bucket',pulse.bucket,'views',pulse.views)) from private.post_view_pulse pulse where pulse.post_id=p.id) as view_pulses
from expected e
left join public.posts p on p.city_id=e.city_id and p.title=e.title and p.status='published'
left join public.profiles pr on pr.id=p.author_id
left join auth.users u on u.id=p.author_id
left join public.tags tag on tag.id=p.tag_id
left join public.cities city on city.id=p.city_id
order by e.ord;